return (async () => {
  const fresh = await window.restService.find('rbuModulesAppeals', appeal._id, false);
  if (!fresh || fresh._id !== appeal._id) throw new Error('Не удалось прочитать актуальное дело отката.');
  const candidates = (fresh.subservices || []).filter(s => s.rbuPetRollbackPlan);
  const current = candidates.find(s => (subservice?.guid && s.guid === subservice.guid) || (subservice?.id && s.id === subservice.id))
    || (candidates.length === 1 ? candidates[0] : null);
  const plan = current?.rbuPetRollbackPlan;
  const saved = current?.xsdData?.rbuPetRollbackConfirmation || {};
  if (!plan || !['PREPARED', 'EXECUTING', 'EXECUTED'].includes(plan.status)) throw new Error('Серверный план отката ещё не готов.');
  if (model?.confirmFinalRollback !== true || saved.confirmFinalRollback !== true
      || model.targetAppealId !== plan.targetAppealId || saved.targetAppealId !== plan.targetAppealId
      || model.journalFingerprint !== plan.journalFingerprint || saved.journalFingerprint !== plan.journalFingerprint) {
    throw new Error('Повторно подтвердите выбранную миграцию и текущий отпечаток журнала.');
  }
  // PGS persists the form; the following external task performs bounded backend deletion.
  return true;
})();

return (async () => {
  const fresh = await window.restService.find('rbuModulesAppeals', appeal._id, false);
  if (!fresh || fresh._id !== appeal._id) throw new Error('Не удалось прочитать актуальное дело отката.');
  const candidates = (fresh.subservices || []).filter(s => s.rbuPetRollbackReport);
  const current = candidates.find(s => (subservice?.guid && s.guid === subservice.guid) || (subservice?.id && s.id === subservice.id))
    || (candidates.length === 1 ? candidates[0] : null);
  if (!['ROLLED_BACK', 'PARTIAL'].includes(current?.rbuPetRollbackReport?.status)) throw new Error('Серверный откат ещё не завершён.');
  return true;
})();

return (async () => {
  const raw = model?.migrationCase || appeal?.migrationCase || subservice?.xsdData?.migrationCase;
  const value = Array.isArray(raw) ? raw[0] : raw;
  const id = String(value?._id || value?.id || value || '').trim();
  if (!id || id === appeal._id) throw new Error('Выберите исходное дело миграции.');
  const confirmed = model?.confirmIrreversible ?? appeal?.confirmIrreversible ?? subservice?.xsdData?.confirmIrreversible;
  if (confirmed !== true) throw new Error('Подтвердите необратимость удаления.');
  const target = await window.restService.find('rbuModulesAppeals', id, false);
  if (!target || target._id !== id || target.status?.code !== 'complete') throw new Error('Исходная миграция должна быть успешно завершена.');
  if (!appeal.unit?.id || target.unit?.id !== appeal.unit.id) throw new Error('Исходная миграция принадлежит другому кабинету.');
  if (target.petMigrationRollback?.completedAt) throw new Error('Эта миграция уже полностью откачена.');
  // The backend verifies the owned worker journal by mainId, including cloned native process keys.
  return true;
})();

return (async () => {
  const fresh = await window.restService.find('rbuModulesAppeals', appeal._id, false);
  if (!fresh || fresh._id !== appeal._id) throw new Error('Не удалось прочитать актуальное дело отката.');
  const candidates = (fresh.subservices || []).filter(s => s.rbuPetRollbackPlan);
  const current = candidates.find(s => (subservice?.guid && s.guid === subservice.guid) || (subservice?.id && s.id === subservice.id))
    || (candidates.length === 1 ? candidates[0] : null);
  const plan = current?.rbuPetRollbackPlan;
  if (!plan || plan.version !== 'rbu-pet-rollback-external-1.0') throw new Error('Серверный план отката ещё не подготовлен.');
  const states = new Set(['PENDING', 'DELETED', 'ALREADY_DELETED', 'BLOCKED', 'ERROR']);
  if (!Array.isArray(plan.rollbackItems) || plan.rollbackItems.some(item => !states.has(item.state))) throw new Error('Сервер вернул неподдерживаемое состояние записи.');
  const checkpoint = new Date(plan.checkpointAt);
  if (Number.isNaN(checkpoint.getTime())) throw new Error('Контрольная точка backend не содержит корректную дату.');
  if (!plan.checkpointTimeDisplay) throw new Error('Не сохранено отображение контрольной точки по московскому времени.');
  const fields = ['totalRecords', 'deletableRecords', 'blockedRecords', 'processedRecords', 'deletedRecords', 'notDeletedRecords',
    'pendingRecords', 'alreadyDeletedRecords', 'technicalErrors', 'currentBatch', 'totalBatches'];
  for (const name of fields) model[name] = Number(plan[name] || 0);
  Object.assign(model, {
    header: 'Удалить импортированные данные «Мой питомец»',
    migrationNumber: plan.targetAppealNumber || plan.targetAppealId,
    sourceFileName: plan.sourceFileName || '—',
    failedRecords: Number(plan.technicalErrors || 0),
    lastSavedAt: plan.checkpointTimeDisplay,
    checkpointAtUtc: checkpoint.toISOString(),
    rollbackItems: plan.rollbackItems.map(item => ({...item})),
    targetAppealId: plan.targetAppealId,
    journalFingerprint: plan.journalFingerprint,
    confirmFinalRollback: false,
    warningText: `Обработано ${plan.processedRecords} из ${plan.totalRecords}. Ожидают: ${plan.pendingRecords}. Уже отсутствовали: ${plan.alreadyDeletedRecords}. Заблокированы: ${plan.blockedRecords}. Ошибок: ${plan.technicalErrors}. Выполнение и продолжение сохраняются серверным обработчиком.`,
  });
  return model;
})();

return (async () => {
  const fresh = await window.restService.find('rbuModulesAppeals', appeal._id, false);
  if (!fresh || fresh._id !== appeal._id) throw new Error('Не удалось прочитать актуальное дело отката.');
  const candidates = (fresh.subservices || []).filter(s => s.rbuPetRollbackReport);
  const current = candidates.find(s => (subservice?.guid && s.guid === subservice.guid) || (subservice?.id && s.id === subservice.id))
    || (candidates.length === 1 ? candidates[0] : null);
  const report = current?.rbuPetRollbackReport;
  if (!report || !['ROLLED_BACK', 'PARTIAL'].includes(report.status)) throw new Error('Итоговый серверный отчёт ещё не готов.');
  const format = (raw) => {
    const date = new Date(raw);
    if (!raw || Number.isNaN(date.getTime())) throw new Error('Некорректная дата серверного отчёта отката.');
    return date.toISOString().replace('T', ' ').replace('Z', ' UTC') + ' / '
      + date.toLocaleString('ru-RU', {timeZone: 'Europe/Moscow', hour12: false}) + ' МСК';
  };
  Object.assign(model, {
    migrationNumber: report.targetAppealNumber || report.targetAppealId,
    sourceFileName: report.sourceFileName || '—',
    startedAt: format(report.startedAt), completedAt: format(report.completedAt),
    resultHeader: report.status === 'ROLLED_BACK' ? 'Удаление данных выполнено полностью' : 'Удаление данных выполнено частично',
    completedBatches: Number(report.lastCompletedBatch || 0), resumeCount: Number(report.resumeCount || 0),
    rollbackMetrics: [
      ['totalRecords', 'Всего записей'], ['deletedRecords', 'Удалено обработчиком'],
      ['alreadyDeletedRecords', 'Отсутствовали до удаления'], ['blockedRecords', 'Заблокировано'],
      ['pendingRecords', 'Ожидают выполнения'], ['technicalErrors', 'Технические ошибки'],
    ].map(([field, label]) => ({metricName: label, recordCount: Number(report[field] || 0)})),
    notDeletedItems: (report.notDeletedItems || []).map(item => ({...item,
      activeAppeals: (item.activeCases || []).map(value => value.number || value.appealId).join(', ')})),
  });
  return model;
})();
